def build_curl_command(method, url, headers, body, auth, auth_type, 
                       proxies, verify, cert, cert_key, ssl_version,
                       timeout, follow, max_redirects, ipv4, ipv6,
                       http_version, unix_socket, resolve, interface,
                       form_params, is_download, output_file, long=False,
                       compress=False, is_multipart=False):
    """Build a curl command translation."""
    parts = []

    # Proxy env vars
    for protocol, proxy_url in (proxies or []):
        if protocol.lower() in ('http', 'all'):
            parts.insert(0, f'http_proxy={proxy_url}')
        if protocol.lower() in ('https', 'all'):
            parts.insert(0, f'https_proxy={proxy_url}')

    parts.append('curl')

    if timeout is not None:
        if long:
            parts.extend(['--max-time', str(timeout)])
        else:
            parts.extend(['--max-time', str(timeout)])

    if verify == 'no' or verify == 'false':
        parts.append('-k' if not long else '--insecure')

    if ipv4:
        parts.append('-4')
    elif ipv6:
        parts.append('-6')

    if follow:
        parts.append('-L' if not long else '--location')
        if max_redirects is not None:
            parts.extend(['--max-redirs' if True else '-', str(max_redirects)])

    if ssl_version and ssl_version != 'auto':
        ver_map = {
            'tls1': ('--tlsv1', '--tls-max 1'),
            'tls1.1': ('--tlsv1.1', '--tls-max 1.1'),
            'tls1.2': ('--tlsv1.2', '--tls-max 1.2'),
            'tls1.3': ('--tlsv1.3', '--tls-max 1.3'),
        }
        if ssl_version in ver_map:
            tls_min, tls_max = ver_map[ssl_version]
            parts.append(tls_min)
            parts.extend(tls_max.split())

    if http_version:
        ver_map = {
            '1.0': '--http1.0',
            '1.1': '--http1.1',
            '2': '--http2',
            '2-prior-knowledge': '--http2-prior-knowledge',
            '3-prior-knowledge': '--http3-only',
        }
        if http_version in ver_map:
            parts.append(ver_map[http_version])

    if is_download:
        if not long:
            parts.extend(['-f', '-L', '-O'])
        else:
            parts.extend(['--fail', '--location', '--remote-name'])

    if output_file and not is_download:
        parts.extend(['-o' if not long else '--output', output_file])

    # Auth
    if auth_type == 'basic':
        parts.append('--basic' if not long else '--basic')
        parts.extend(['-u' if not long else '--user', auth])
    elif auth_type == 'bearer':
        parts.extend(['--oauth2-bearer', auth])
    elif auth_type == 'digest':
        parts.append('--digest')
        parts.extend(['-u' if not long else '--user', auth])

    # Method
    method_flag = '-X' if not long else '--request'
    parts.extend([method_flag, method])

    # URL
    parts.append(url)

    # Headers
    header_flag = '-H' if not long else '--header'
    for name, value in headers:
        name_lower = name.lower()
        if name_lower in ('content-type', 'accept'):
            parts.extend([header_flag, f'{name_lower}: {value}'])
        else:
            parts.extend([header_flag, f'{name_lower}: {value}'])

    # Resolve
    for resolve_entry in (resolve or []):
        sys.stderr.write(f"Warning: Inferred port number in --resolve from request URL.\n")
        parts.extend(['--resolve', resolve_entry])

    # Unix socket
    if unix_socket:
        parts.extend(['--unix-socket', unix_socket])

    # Interface
    if interface:
        parts.extend(['--interface', interface])

    # Form params
    if form_params:
        data_flag = '--data-urlencode' if not long else '--data-urlencode'
        for k, v in form_params:
            parts.extend([data_flag, f'{k}={v}'])
    elif body is not None:
        data_flag = '-d' if not long else '--data'
        if isinstance(body, bytes):
            try:
                body_str = body.decode('utf-8')
                parts.extend([data_flag, body_str])
            except:
                parts.extend([data_flag, '@-'])
        else:
            parts.extend([data_flag, str(body)])

    # Format the command
    # Add single quotes around args that need them
    result = []
    for i, part in enumerate(parts):
        if i == 0 and '=' in part and not part.startswith('-'):
            # Env var
            result.append(part)
        elif ' ' in part or "'" in part or any(c in part for c in ';&|<>()$`\\"\t\n'):
            result.append(f"'{part}'")
        else:
            result.append(part)

    return ' '.join(result)


def get_config_dir():
    """Get the xh config directory."""
    env = os.environ.get('XH_CONFIG_DIR')
    if env:
        return env

    home = os.path.expanduser('~')
    if platform.system() == 'Windows':
        appdata = os.environ.get('APPDATA', home)
        return os.path.join(appdata, 'xh')
    else:
        xdg = os.environ.get('XDG_CONFIG_HOME', os.path.join(home, '.config'))
        return os.path.join(xdg, 'xh')


def load_config():
    """Load config.json from config dir."""
    config_dir = get_config_dir()
    config_file = os.path.join(config_dir, 'config.json')

    if not os.path.exists(config_file):
        return {}

    try:
        with open(config_file, 'r') as f:
            return json.load(f)
    except:
        return {}


def get_netrc_auth(host):
    """Get auth from .netrc file."""
    netrc_file = os.environ.get('NETRC')
    if not netrc_file:
        home = os.path.expanduser('~')
        netrc_file = os.path.join(home, '.netrc')
        if not os.path.exists(netrc_file):
            netrc_file = os.path.join(home, '_netrc')

    if not os.path.exists(netrc_file):
        return None

    try:
        import netrc
        nrc = netrc.netrc(netrc_file)
        auth = nrc.authenticators(host)
        if auth:
            return auth[0], auth[2]  # login, password
    except Exception:
        pass

    return None


