        else:
            response = opener.open(req)

        elapsed = time.monotonic() - start

        status_code = response.getcode()

        # Get response headers
        resp_headers = []
        for key in response.headers:
            resp_headers.append((key, response.headers[key]))

        # Get HTTP version
        http_ver = "1.1"  # Default

        # Get remote addr
        remote_addr_str = f"{actual_host}:{port}"

