        resp_headers = []
        for key in e.headers:
            resp_headers.append((key, e.headers[key]))

        reason = e.reason if e.reason else http.client.responses.get(e.code, '')

        resp_body = e.read() if e.fp else b''

        # Get HTTP version
        http_ver = "1.1"

        remote_addr_str = f"{actual_host}:{port}"

        # Decompress
        ce = e.headers.get('Content-Encoding', '').lower()
        if 'gzip' in ce:
            import gzip
            try:
                resp_body = gzip.decompress(resp_body)
            except:
