            headers=resp_headers,
            body=resp_body,
            url=url,
            elapsed=elapsed,
            remote_addr=remote_addr_str
        )

        return resp_obj, elapsed

    except urllib.error.URLError as e:
        elapsed = time.monotonic() - start_time
        reason = str(e.reason)
        raise ConnectionError(f"error sending request for url ({url})\n\nCaused by:\n    {reason}")

