def _cookie_matches(cookie, parsed_url):
    """Check if a cookie matches the URL."""
    domain = cookie.get('domain', '')
    path = cookie.get('path', '/')

    if not domain or parsed_url.hostname in (domain, domain.lstrip('.')):
        if parsed_url.path.startswith(path):
            return True

    return False


def _parse_set_cookie(header_val, parsed_url, cookie_jar):
    """Parse Set-Cookie header and add to jar."""
    parts = header_val.split(';')
    if not parts:
        return

    name_val = parts[0].strip()
    if '=' not in name_val:
        return

    name, _, value = name_val.partition('=')
    name = name.strip()
    value = value.strip()

    cookie = {
        'name': name,
        'value': value,
        'path': '/',
        'domain': parsed_url.hostname,
    }

    for part in parts[1:]:
        part = part.strip()
        if part.lower().startswith('path='):
            cookie['path'] = part[5:]
        elif part.lower().startswith('domain='):
            cookie['domain'] = part[7:].lstrip('.')
        elif part.lower() == 'secure':
            cookie['secure'] = True
        elif part.lower() == 'httponly':
            cookie['httponly'] = True

    # Update existing cookie or add new one
    for i, existing in enumerate(cookie_jar):
        if existing['name'] == name and existing.get('domain') == cookie.get('domain'):
            cookie_jar[i] = cookie
            return

    cookie_jar.append(cookie)


