    opener = urllib.request.build_opener(*handlers)

    try:
        if timeout:
            response = opener.open(req, timeout=float(timeout))
        else:
            response = opener.open(req)

        content_length = response.headers.get('Content-Length')
        total = int(content_length) if content_length else None

        if total and start_byte:
            total += start_byte

        if output_path:
            fname = output_path
        else:
            # Determine filename from URL
            path = urllib.parse.urlparse(url).path
            fname = os.path.basename(path) or 'index.html'

        # Print download header
        if total:
            stream.write(f'Downloading {format_size(total)} to "{fname}"\n')
        else:
            stream.write(f'Downloading to "{fname}"\n')
        stream.flush()

        mode = 'ab' if resume and start_byte > 0 else 'wb'
        downloaded = start_byte
        chunk_size = 8192

        start = time.monotonic()
        with open(fname, mode) as f:
            while True:
                chunk = response.read(chunk_size)
                if not chunk:
                    break
                f.write(chunk)
                downloaded += len(chunk)

        elapsed = time.monotonic() - start
        speed = downloaded / elapsed if elapsed > 0 else 0
        stream.write(f'Done. {format_size(downloaded)} in {elapsed:.5f}s ({format_size(speed)}/s)\n')
        stream.flush()

        return True

    except Exception as e:
        raise ConnectionError(f"error downloading {url}: {e}")


