def colorize_header_line(name, value, theme_name):
    t = get_theme(theme_name)
    R = RESET
    nl = t['nl']
    return f"{R}{t['header_name']}{name}{R}{t['colon']}:{R} {R}{t['header_val']}{value}{R}{nl}"


def colorize_json(text, theme_name):
    """Colorize JSON text using manual token-based approach."""
    t = get_theme(theme_name)
    R = RESET
    result = [R]
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        if ch == '"':
            # String - determine if key or value
            j = i + 1
            s_inner = []
            while j < n:
                c = text[j]
                if c == '\\' and j + 1 < n:
                    s_inner.append(c)
                    j += 1
                    s_inner.append(text[j])
                elif c == '"':
                    j += 1
                    break
                else:
                    s_inner.append(c)
                j += 1
            s_content = ''.join(s_inner)

            # Look ahead to determine key vs value
            k = j
            while k < n and text[k] in ' \t\n\r':
                k += 1

            if k < n and text[k] == ':':
                color = t['json_key']
            else:
                color = t['json_str']

            result.append(f"{color}\"{R}{color}{s_content}{R}{color}\"{R}")
            i = j
            continue

        elif ch in '{}[],:':
            result.append(f"{t['json_punct']}{ch}{R}")

        elif ch in ' \t\n\r':
            result.append(ch)

        elif text[i:i+4] == 'true':
            result.append(f"{t['json_bool']}true{R}")
            i += 4
            continue

        elif text[i:i+5] == 'false':
            result.append(f"{t['json_bool']}false{R}")
            i += 5
            continue

        elif text[i:i+4] == 'null':
            result.append(f"{t['json_null']}null{R}")
            i += 4
            continue

        elif ch == '-' or ch.isdigit():
            j = i
            while j < n and (text[j] in '0123456789.-+eE'):
                j += 1
            result.append(f"{t['json_num']}{text[i:j]}{R}")
            i = j
            continue

        else:
            result.append(ch)

        i += 1

    return ''.join(result)


def format_json_pretty(text, indent=4):
    """Pretty-print JSON with specified indent."""
    try:
        obj = json.loads(text)
        return json.dumps(obj, indent=indent, ensure_ascii=False)
    except (json.JSONDecodeError, ValueError):
        return text


def is_json_content_type(ct):
    if not ct:
        return False
    ct = ct.lower().split(';')[0].strip()
    return ct in ('application/json', 'text/json') or '+json' in ct


def is_text_content_type(ct):
    if not ct:
        return False
    ct_base = ct.lower().split(';')[0].strip()
    return (ct_base.startswith('text/') or
            ct_base in ('application/json', 'application/xml',
                        'application/javascript', 'application/x-www-form-urlencoded') or
            '+json' in ct_base or '+xml' in ct_base)


BINARY_MSG = "+-----------------------------------------+\n| NOTE: binary data not shown in terminal |\n+-----------------------------------------+\n"


def write_output(data, stream):
    """Write data to stream, handling bytes vs str."""
    if isinstance(data, bytes):
        if hasattr(stream, 'buffer'):
            stream.buffer.write(data)
        elif hasattr(stream, 'write'):
            try:
                stream.write(data.decode('utf-8', errors='replace'))
            except Exception:
                pass
    else:
        if hasattr(stream, 'buffer'):
            stream.buffer.write(data.encode('utf-8', errors='replace'))
        elif hasattr(stream, 'write'):
            stream.write(data)


def print_headers_block(status_line, headers, do_color, do_format, theme_name,
                         sort_headers=True, stream=None):
    """Print an HTTP headers block."""
    if stream is None:
        stream = sys.stdout

    headers_list = list(headers)
    if do_format and sort_headers:
        headers_list = sorted(headers_list, key=lambda h: h[0].lower())

    lines = []
    if do_color:
        # Colorize status line
        if status_line.startswith('HTTP/') or status_line.startswith('HTTP '):
            m = re.match(r'HTTP/(\S+)\s+(\d+)\s*(.*)', status_line)
            if m:
                lines.append(colorize_response_line(m.group(1), m.group(2), m.group(3).rstrip(), theme_name))
            else:
                lines.append(status_line)
        else:
            parts = status_line.split(' ', 2)
            if len(parts) >= 3:
                method, path = parts[0], parts[1]
                ver = parts[2].replace('HTTP/', '')
                lines.append(colorize_request_line(method, path, ver, theme_name))
            elif len(parts) == 2:
                method, path = parts[0], parts[1]
                lines.append(colorize_request_line(method, path, '1.1', theme_name))
            else:
                lines.append(status_line)

        for name, value in headers_list:
            lines.append(colorize_header_line(name, value, theme_name))

        t = get_theme(theme_name)
        lines.append(RESET)
    else:
        lines.append(status_line)
        for name, value in headers_list:
            lines.append(f"{name}: {value}")
        lines.append("")

    output = '\n'.join(lines) + '\n'
    write_output(output, stream)


def print_body(body_bytes, content_type, do_color, do_format, theme_name,
               json_indent=4, json_format=True, stream=None, is_request=False,
               charset=None):
    """Print a body block."""
    if stream is None:
        stream = sys.stdout

    # Check if text
    if is_text_content_type(content_type):
        # Decode text
        enc = charset or 'utf-8'
        # Try to get encoding from content-type
        if ';' in content_type:
            for part in content_type.split(';'):
                part = part.strip()
                if part.startswith('charset='):
                    enc = part[8:].strip('"\'')
        try:
            text = body_bytes.decode(enc, errors='replace')
        except Exception:
            text = body_bytes.decode('latin-1', errors='replace')

        # Apply JSON formatting
        if is_json_content_type(content_type) and json_format and do_format:
            text = format_json_pretty(text, indent=json_indent)

        # Apply coloring
        if do_color and is_json_content_type(content_type):
            text = colorize_json(text, theme_name)

        # Add trailing newlines
        if is_request:
            # Request body always gets \n\n
            if not text.endswith('\n'):
                text += '\n'
            text += '\n'
        elif do_format:
            # Response body with format gets \n\n
            if not text.endswith('\n'):
                text += '\n'
            text += '\n'
        # else: no trailing newline for response with pretty=none

        write_output(text, stream)
    else:
        # Binary data
        if is_request:
            write_output(BINARY_MSG + '\n', stream)
        else:
            write_output(BINARY_MSG + '\n', stream)


def header_canonical(name):
    """Convert header name to Title-Case."""
    return '-'.join(part.capitalize() for part in name.split('-'))


def parse_item(item):
    """Parse a request item, returning (key, sep, value)."""
    i = 0
    n = len(item)
    while i < n:
        if item[i] == '\\' and i + 1 < n:
            i += 2
            continue

        # Two-char seps first
        if i + 1 < n:
            two = item[i:i+2]
            if two == ':=':
                return unescape(item[:i]), ':=', item[i+2:]
            if two == '==':
                return unescape(item[:i]), '==', item[i+2:]

        ch = item[i]
        if ch == '=':
            return unescape(item[:i]), '=', item[i+1:]
        if ch == '@' and i > 0:  # Only if not at start
            return unescape(item[:i]), '@', item[i+1:]
        if ch == ':':
            return unescape(item[:i]), ':', item[i+1:]
        if ch == ';':
            return unescape(item[:i]), ';', item[i+1:]

        i += 1

    return item, None, None


def unescape(s):
    result = []
    i = 0
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s):
            result.append(s[i+1])
            i += 2
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)


def parse_request_items(items):
    """Parse request items. Returns (headers_list, body_params, query_params, files, body_file).

    headers_list: [(name, value)] - value=None means remove this header
    body_params: [('string'|'json', key, value)]
    query_params: [(key, value)]
    files: [(key, filepath, mime_type, filename)]
    body_file: str or None
    """
    headers = []
    body_params = []
    query_params = []
    files = []
    body_file = None

    for item in items:
        # Check for @filename (body from file)
        if item.startswith('@'):
            body_file = item[1:]
            continue

        key, sep, value = parse_item(item)

        if sep is None:
            sys.stderr.write(f"xh: error: failed to parse '{item}'\n")
            sys.exit(1)

        if sep == '==':
            query_params.append((key, value))

        elif sep == '=':
            if value.startswith('@'):
                # Value from file
                filepath = value[1:]
                try:
                    with open(filepath, 'rb') as f:
                        raw = f.read()
                    try:
                        value = raw.decode('utf-8')
                    except UnicodeDecodeError:
                        value = raw.decode('latin-1')
                except (IOError, OSError) as e:
                    sys.stderr.write(f"xh: error: cannot read '{filepath}': {e}\n")
                    sys.exit(1)
            body_params.append(('string', key, value))

        elif sep == ':=':
            if value.startswith('@'):
                filepath = value[1:]
                try:
                    with open(filepath, 'r') as f:
                        value = f.read()
                except (IOError, OSError) as e:
                    sys.stderr.write(f"xh: error: cannot read '{filepath}': {e}\n")
                    sys.exit(1)
            body_params.append(('json', key, value))

        elif sep == '@':
            # File upload for multipart: key@filepath[;type=mime][;filename=name]
            parts = value.split(';')
            filepath = parts[0]
            mime_type = None
            filename = None
            for p in parts[1:]:
                if p.startswith('type='):
                    mime_type = p[5:]
                elif p.startswith('filename='):
                    filename = p[9:]
            files.append((key, filepath, mime_type, filename))

        elif sep == ':':
            # Header: empty value means remove
            if value.startswith('@'):
                filepath = value[1:]
                try:
                    with open(filepath, 'rb') as f:
                        raw = f.read()
                    try:
                        v = raw.decode('utf-8').rstrip('\n').rstrip('\r')
                    except UnicodeDecodeError:
                        v = raw.decode('latin-1').rstrip('\n').rstrip('\r')
                    if '\n' in v or '\r' in v:
                        sys.stderr.write(f"xh: error: failed to parse header value\n")
                        sys.exit(1)
                    value = v
                except (IOError, OSError) as e:
                    sys.stderr.write(f"xh: error: cannot read '{filepath}': {e}\n")
                    sys.exit(1)
            # Empty value from ':' separator means REMOVE the header
            if value == '':
                headers.append((header_canonical(key), None))  # None = remove
            else:
                headers.append((header_canonical(key), value))

        elif sep == ';':
            # Header with empty value
            headers.append((header_canonical(key), ''))

    return headers, body_params, query_params, files, body_file


def set_nested(obj, key, value):
    """Set nested value using JSON path notation like app[container][0][id]."""
    parts = parse_key_path(key)

    if len(parts) == 1:
        obj[parts[0]] = value
        return

    current = obj
    for idx, part in enumerate(parts[:-1]):
        next_part = parts[idx + 1]

        if isinstance(current, dict):
            if part not in current:
                if isinstance(next_part, int):
                    current[part] = []
                else:
                    current[part] = {}
            current = current[part]
        elif isinstance(current, list):
            # Ensure list is large enough
            while len(current) <= part:
                if isinstance(next_part, int):
                    current.append([])
                else:
                    current.append({})
            if current[part] is None:
                if isinstance(next_part, int):
                    current[part] = []
                else:
                    current[part] = {}
            current = current[part]

    last = parts[-1]
    if isinstance(current, dict):
        current[last] = value
    elif isinstance(current, list):
        while len(current) <= last:
            current.append(None)
        current[last] = value


def parse_key_path(key):
    """Parse key path like 'app[0][name]' into ['app', 0, 'name']."""
    parts = []
    segments = re.split(r'\[', key)
    parts.append(segments[0])
    for seg in segments[1:]:
        seg = seg.rstrip(']')
        try:
            parts.append(int(seg))
        except ValueError:
            parts.append(seg)
    return parts


def build_json_body(params):
    """Build JSON body from params list."""
    obj = {}
    for ptype, key, value in params:
        if ptype == 'string':
            set_nested(obj, key, value)
        else:
            try:
                parsed = json.loads(value)
            except json.JSONDecodeError:
                sys.stderr.write(f"xh: error: '{value}' is not valid JSON\n")
                sys.exit(1)
            set_nested(obj, key, parsed)
    return json.dumps(obj, ensure_ascii=False, separators=(',', ':'))


def build_form_body(params):
    """Build URL-encoded form body."""
    pairs = []
    for _, key, value in params:
        pairs.append((key, value))
    return urllib.parse.urlencode(pairs)


def build_multipart_body(params, files):
    """Build multipart/form-data body."""
    boundary = '-'.join([uuid.uuid4().hex[:16] for _ in range(4)])
    parts = []

    for _, key, value in params:
        part = (
            f'--{boundary}\r\n'
            f'Content-Disposition: form-data; name="{key}"\r\n'
            f'\r\n'
            f'{value}\r\n'
        ).encode()
        parts.append(part)

    for key, filepath, mime_type, filename in files:
        if filename is None:
            filename = os.path.basename(filepath)
        if mime_type is None:
            mime_type, _ = mimetypes.guess_type(filepath)

        try:
            with open(filepath, 'rb') as f:
                file_data = f.read()
        except (IOError, OSError) as e:
            sys.stderr.write(f"xh: error: cannot read '{filepath}': {e}\n")
            sys.exit(1)

        cd = f'Content-Disposition: form-data; name="{key}"; filename="{filename}"\r\n'
        ct = f'Content-Type: {mime_type}\r\n' if mime_type else ''
        header = f'--{boundary}\r\n{cd}{ct}\r\n'.encode()
        parts.append(header + file_data + b'\r\n')

    body = b''.join(parts) + f'--{boundary}--\r\n'.encode()
    ct = f'multipart/form-data; boundary={boundary}'
    return body, ct


def deflate_compress(data):
    """Compress using deflate."""
    return zlib.compress(data)[2:-4]


def normalize_url(url, default_scheme='http'):
    """Normalize URL, handling localhost shorthand."""
    if url.startswith('://'):
        url = url[3:]

    if url.startswith(':'):
        rest = url[1:]
        if rest.startswith('/'):
            url = 'localhost' + url
        else:
            url = 'localhost' + url

    if '://' not in url:
        url = default_scheme + '://' + url

    return url


def get_config_dir():
    env = os.environ.get('XH_CONFIG_DIR')
    if env:
        return env
    home = os.path.expanduser('~')
    if platform.system() == 'Windows':
        appdata = os.environ.get('APPDATA', home)
        return os.path.join(appdata, 'xh')
    xdg = os.environ.get('XDG_CONFIG_HOME', os.path.join(home, '.config'))
    return os.path.join(xdg, 'xh')


def load_config():
    config_dir = get_config_dir()
    config_file = os.path.join(config_dir, 'config.json')
    if not os.path.exists(config_file):
        return {}
    try:
        with open(config_file, 'r') as f:
            return json.load(f)
    except Exception:
        return {}


def get_netrc_auth(host):
    netrc_file = os.environ.get('NETRC')
    if not netrc_file:
        home = os.path.expanduser('~')
        netrc_file = os.path.join(home, '.netrc')
        if not os.path.exists(netrc_file):
            netrc_file = os.path.join(home, '_netrc')
    if not os.path.exists(netrc_file):
        return None
    try:
        import netrc
        nrc = netrc.netrc(netrc_file)
        auth = nrc.authenticators(host)
        if auth:
            return auth[0], auth[2]
    except Exception:
        pass
    return None


def load_session(session_file):
    if not os.path.exists(session_file):
        return {
            "__meta__": {"about": "xh session file", "xh": VERSION},
            "auth": {"type": None, "raw_auth": None},
            "cookies": [],
            "headers": []
        }
    try:
        with open(session_file, 'r') as f:
            return json.load(f)
    except Exception:
        return {
            "__meta__": {"about": "xh session file", "xh": VERSION},
            "auth": {"type": None, "raw_auth": None},
            "cookies": [],
            "headers": []
        }


def save_session(session_file, data, prog='xh'):
    try:
        import tempfile
        dir_name = os.path.dirname(os.path.abspath(session_file))
        os.makedirs(dir_name, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=dir_name, prefix='.xh-sess-')
        try:
            with os.fdopen(fd, 'w') as f:
                json.dump(data, f, indent=4)
                f.write('\n')
            os.rename(tmp, session_file)
        except Exception:
            try:
                os.unlink(tmp)
            except Exception:
                pass
            raise
    except (IOError, OSError) as e:
        sys.stderr.write(f"{prog}: error: couldn't persist session {session_file}\n\nCaused by:\n    {e}\n")
        sys.exit(1)


def cookie_matches(cookie, hostname, path, scheme):
    domain = cookie.get('domain', hostname)
    cookie_path = cookie.get('path', '/')

    host_match = (hostname == domain or hostname.endswith('.' + domain) or 
                  domain == hostname)
    path_match = path.startswith(cookie_path)

    if cookie.get('secure') and scheme != 'https':
        return False

    return host_match and path_match


def parse_set_cookie(header_val, hostname):
    """Parse Set-Cookie header and return cookie dict."""
    parts = header_val.split(';')
    if not parts:
        return None

    name_val = parts[0].strip()
    if '=' not in name_val:
        return None

    name, _, value = name_val.partition('=')
    cookie = {
        'name': name.strip(),
        'value': value.strip(),
        'path': '/',
        'domain': hostname,
    }

    for part in parts[1:]:
        part = part.strip()
        pl = part.lower()
        if pl.startswith('path='):
            cookie['path'] = part[5:]
        elif pl.startswith('domain='):
            d = part[7:]
            if d.startswith('.'):
                d = d[1:]
            cookie['domain'] = d
        elif pl == 'secure':
            cookie['secure'] = True
        elif pl == 'httponly':
            cookie['httponly'] = True

    return cookie


class HTTPResult:
    def __init__(self, status_code, status_text, http_version, headers, body,
                 remote_addr, elapsed):
        self.status_code = status_code
        self.status_text = status_text
        self.http_version = http_version
        self.headers = headers  # list of (name, value)
        self.body = body  # bytes
        self.remote_addr = remote_addr
        self.elapsed = elapsed


def make_http_request(method, url, headers_list, body, timeout, verify, cert,
                      cert_key, ssl_ver, proxies, cookie_jar, follow_redirects,
                      max_redirects):
    """Make HTTP request. Returns HTTPResult."""

    start = time.monotonic()

    parsed = urllib.parse.urlparse(url)
    hostname = parsed.hostname
    port = parsed.port or (443 if parsed.scheme == 'https' else 80)
    is_https = parsed.scheme == 'https'

    # Build SSL context
    ssl_context = None
    if is_https:
        ssl_context = ssl.create_default_context()
        v = verify
        if v in (None, 'yes', 'true', True):
            pass  # default verification
        elif v in ('no', 'false', False):
            ssl_context.check_hostname = False
            ssl_context.verify_mode = ssl.CERT_NONE
        else:
            # CA bundle file
            ssl_context = ssl.create_default_context(cafile=v)

        if cert:
            if cert_key:
                ssl_context.load_cert_chain(cert, cert_key)
            else:
                ssl_context.load_cert_chain(cert)

        if ssl_ver and ssl_ver != 'auto':
            ver_map = {
                'tls1': ssl.TLSVersion.TLSv1,
                'tls1.1': ssl.TLSVersion.TLSv1_1,
                'tls1.2': ssl.TLSVersion.TLSv1_2,
                'tls1.3': ssl.TLSVersion.TLSv1_3,
            }
            if ssl_ver in ver_map:
                try:
                    ssl_context.minimum_version = ver_map[ssl_ver]
                    ssl_context.maximum_version = ver_map[ssl_ver]
                except AttributeError:
                    pass

    # Build proxy handler
    handlers = []
    if proxies:
        proxy_dict = {}
        for proto, purl in proxies:
            if proto.lower() == 'all':
                proxy_dict['http'] = purl
                proxy_dict['https'] = purl
            else:
                proxy_dict[proto.lower()] = purl
        handlers.append(urllib.request.ProxyHandler(proxy_dict))

    if ssl_context:
        handlers.append(urllib.request.HTTPSHandler(context=ssl_context))

    # No auto-redirect
    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, req, fp, code, msg, headers, newurl):
            return None
        def http_error_301(self, req, fp, code, msg, hdrs): return fp
        def http_error_302(self, req, fp, code, msg, hdrs): return fp
        def http_error_303(self, req, fp, code, msg, hdrs): return fp
        def http_error_307(self, req, fp, code, msg, hdrs): return fp
        def http_error_308(self, req, fp, code, msg, hdrs): return fp

    handlers.append(NoRedirect())
    handlers.append(urllib.request.HTTPErrorHandler())

    opener = urllib.request.build_opener(*handlers)

    req_headers_dict = {}
    for name, value in headers_list:
        req_headers_dict[name] = value

    # Add cookies
    if cookie_jar:
        cookie_strs = []
        for c in cookie_jar:
            if cookie_matches(c, hostname, parsed.path or '/', parsed.scheme):
                cookie_strs.append(f"{c['name']}={c['value']}")
        if cookie_strs:
            req_headers_dict['Cookie'] = '; '.join(cookie_strs)

    def do_request(url, method, body, req_headers_dict):
        req = urllib.request.Request(url, data=body, headers=req_headers_dict, method=method)

        try:
            to = float(timeout) if timeout is not None else None
            if to is not None:
                response = opener.open(req, timeout=to)
            else:
                response = opener.open(req)

            status = response.getcode()
            reason = getattr(response, 'reason', '') or http.client.responses.get(status, '')

            # Get HTTP version
            http_ver = '1.1'
            if hasattr(response, 'version'):
                v = response.version
                if v == 10:
                    http_ver = '1.0'
                elif v == 11:
                    http_ver = '1.1'
                elif v == 20:
                    http_ver = '2'

            # Collect headers
            resp_headers = []
            for k in response.headers:
                resp_headers.append((k, response.headers[k]))

            # Read body
            resp_body = response.read()

            # Decompress
            ce = response.headers.get('Content-Encoding', '').lower()
            if 'gzip' in ce:
                import gzip
                try:
                    resp_body = gzip.decompress(resp_body)
                except Exception:
                    pass
            elif 'deflate' in ce:
                try:
                    resp_body = zlib.decompress(resp_body)
                except Exception:
                    try:
                        resp_body = zlib.decompress(resp_body, -15)
                    except Exception:
                        pass

            # Update cookies
            if cookie_jar is not None:
                for hv in response.headers.get_all('Set-Cookie') or []:
                    c = parse_set_cookie(hv, hostname)
                    if c:
                        # Update existing or add
                        updated = False
                        for i, existing in enumerate(cookie_jar):
                            if (existing['name'] == c['name'] and
                                    existing.get('domain') == c.get('domain')):
                                cookie_jar[i] = c
                                updated = True
                                break
                        if not updated:
                            cookie_jar.append(c)

            return status, reason, http_ver, resp_headers, resp_body, response

        except urllib.error.HTTPError as e:
            status = e.code
            reason = e.reason or http.client.responses.get(status, '')

            resp_headers = []
            for k in e.headers:
                resp_headers.append((k, e.headers[k]))

            http_ver = '1.1'
            resp_body = b''
            if e.fp:
                try:
                    resp_body = e.read()
                except Exception:
                    pass

            # Decompress
            ce = e.headers.get('Content-Encoding', '').lower()
            if 'gzip' in ce:
                import gzip
                try:
                    resp_body = gzip.decompress(resp_body)
                except Exception:
                    pass

            # Update cookies
            if cookie_jar is not None:
                for hv in (e.headers.get_all('Set-Cookie') or []):
                    c = parse_set_cookie(hv, hostname)
                    if c:
                        updated = False
                        for i, existing in enumerate(cookie_jar):
                            if (existing['name'] == c['name'] and
                                    existing.get('domain') == c.get('domain')):
                                cookie_jar[i] = c
                                updated = True
                                break
                        if not updated:
                            cookie_jar.append(c)

            return status, reason, http_ver, resp_headers, resp_body, None

    # Handle redirects manually if requested
    redirect_count = 0
    current_url = url
    current_method = method
    current_body = body
    current_headers = dict(req_headers_dict)

    while True:
        try:
            status, reason, http_ver, resp_headers, resp_body, raw_resp = do_request(
                current_url, current_method, current_body, current_headers
            )
        except urllib.error.URLError as e:
            elapsed = time.monotonic() - start
            raise ConnectionError(
                f"error sending request for url ({current_url})\n\nCaused by:\n    {e.reason}"
            )
        except socket.timeout:
            elapsed = time.monotonic() - start
            raise TimeoutError(f"timed out waiting for {current_url}")
        except Exception as e:
            elapsed = time.monotonic() - start
            raise ConnectionError(
                f"error sending request for url ({current_url})\n\nCaused by:\n    {e}"
            )

        elapsed = time.monotonic() - start

        if not follow_redirects:
            break

        if status not in (301, 302, 303, 307, 308):
            break

        if redirect_count >= (max_redirects or 30):
            break

        redirect_count += 1

        # Get Location header
        location = None
        for k, v in resp_headers:
            if k.lower() == 'location':
                location = v
                break

        if not location:
            break

        # Resolve relative URL
        current_url = urllib.parse.urljoin(current_url, location)

        # 303: always GET, 301/302: usually GET for non-GET methods
        if status in (301, 302, 303):
            current_method = 'GET'
            current_body = None
            # Remove body-related headers
            for k in list(current_headers.keys()):
                if k.lower() in ('content-type', 'content-length', 'content-encoding'):
                    del current_headers[k]

    remote_addr = f"{hostname}:{port}"

    return HTTPResult(
        status_code=status,
        status_text=reason,
        http_version=http_ver,
        headers=resp_headers,
        body=resp_body,
        remote_addr=remote_addr,
        elapsed=elapsed,
    )


def format_size(size):
    if size < 1024:
        return f"{size} B"
    elif size < 1024 * 1024:
        return f"{size/1024:.2f} KiB"
    elif size < 1024 * 1024 * 1024:
        return f"{size/(1024*1024):.2f} MiB"
    else:
        return f"{size/(1024*1024*1024):.2f} GiB"


def build_curl_cmd(method, url, headers_list, body, auth_type, auth_creds,
                   proxies, verify, cert, cert_key, ssl_ver, timeout,
                   follow, max_redirects, ipv4, ipv6, http_version,
                   unix_socket, resolve, interface, form_params,
                   is_download, output_file, long=False):
    parts = []

    # Prefix env vars for proxies
    proxy_envs = []
    if proxies:
        for proto, purl in proxies:
            if proto.lower() in ('http', 'all'):
                proxy_envs.append(f'http_proxy={purl}')
            if proto.lower() in ('https', 'all'):
                proxy_envs.append(f'https_proxy={purl}')

    parts = proxy_envs + ['curl']

    if timeout is not None:
        parts.extend(['--max-time', str(timeout)])

    if ipv4:
        parts.append('-4')
    elif ipv6:
        parts.append('-6')

    if ssl_ver and ssl_ver != 'auto':
        ver_map = {
            'tls1': ('--tlsv1', '--tls-max', '1'),
            'tls1.1': ('--tlsv1.1', '--tls-max', '1.1'),
            'tls1.2': ('--tlsv1.2', '--tls-max', '1.2'),
            'tls1.3': ('--tlsv1.3', '--tls-max', '1.3'),
        }
        if ssl_ver in ver_map:
            vt = ver_map[ssl_ver]
            parts.append(vt[0])
            parts.extend([vt[1], vt[2]])

    if verify in ('no', 'false'):
        parts.append('-k' if not long else '--insecure')

    if http_version:
        ver_map = {
            '1.0': '--http1.0',
            '1.1': '--http1.1',
            '2': '--http2',
            '2-prior-knowledge': '--http2-prior-knowledge',
            '3-prior-knowledge': '--http3-only',
        }
        if http_version in ver_map:
            parts.append(ver_map[http_version])

    if follow:
        parts.append('-L' if not long else '--location')
        if max_redirects is not None:
            parts.extend(['--max-redirs', str(max_redirects)])

    if is_download:
        parts.extend(['-f', '-L', '-O'] if not long else ['--fail', '--location', '--remote-name'])

    if auth_type == 'basic':
        parts.extend(['--basic', '-u' if not long else '--user', auth_creds])
    elif auth_type == 'bearer':
        parts.extend(['--oauth2-bearer', auth_creds])
    elif auth_type == 'digest':
        parts.extend(['--digest', '-u' if not long else '--user', auth_creds])

    method_flag = '-X' if not long else '--request'
    parts.extend([method_flag, method])

    parts.append(url)

    header_flag = '-H' if not long else '--header'
    auto_skip = {'accept-encoding', 'user-agent', 'connection', 'host', 'content-length'}
    for name, value in headers_list:
        if name.lower() in auto_skip:
            continue
        parts.extend([header_flag, f'{name.lower()}: {value}'])

    if resolve:
        parsed_url = urllib.parse.urlparse(url)
        port = parsed_url.port or (443 if parsed_url.scheme == 'https' else 80)
        for r in resolve:
            sys.stderr.write("Warning: Inferred port number in --resolve from request URL.\n")
            if ':' in r:
                rhost, raddr = r.rsplit(':', 1)
                parts.extend(['--resolve', f'{rhost}:{port}:{raddr}'])

    if unix_socket:
        parts.extend(['--unix-socket', unix_socket])

    if interface:
        parts.extend(['--interface', interface])

    if form_params:
        flag = '--data-urlencode'
        for k, v in form_params:
            parts.extend([flag, f'{k}={v}'])
    elif body is not None:
        data_flag = '-d' if not long else '--data'
        if isinstance(body, bytes):
            try:
                bs = body.decode('utf-8')
                parts.extend([data_flag, bs])
            except Exception:
                parts.extend([data_flag, '@-'])
        else:
            parts.extend([data_flag, str(body)])

    # Format with shell quoting
    result_parts = []
    for i, p in enumerate(parts):
        if i < len(proxy_envs) and '=' in p:
            result_parts.append(p)
        elif any(c in p for c in ' \t\'"|&;$<>()\\`\n'):
            result_parts.append("'" + p.replace("'", "'\\''") + "'")
        else:
            result_parts.append(p)

    return ' '.join(result_parts)


