def main():
    argv = sys.argv
    prog = os.path.basename(argv[0])

    # Determine mode
    httpie_compat = (
        prog in ('http', 'https') or
        os.environ.get('XH_HTTPIE_COMPAT_MODE', '').lower() in ('1', 'true', 'yes')
    )
    force_https = prog in ('xhs', 'https', 'xhttps')

    args_list = list(argv[1:])

    # Handle 'help' subcommand
    if args_list and args_list[0] == 'help':
        print_long_help(prog)
        sys.exit(0)

    # Load config
    config = load_config()
    default_options = config.get('default_options', [])
    if default_options:
        args_list = list(default_options) + args_list

    parser = create_arg_parser(prog)

    try:
        ns, remaining = parser.parse_known_args(args_list)
    except SystemExit as e:
        sys.exit(int(str(e.code)) if e.code is not None else 1)

    if ns.version:
        sys.stdout.write(f"xh {VERSION}\n-native-tls +rustls\n")
        sys.exit(0)

    if ns.help:
        print_short_help(prog)
        sys.exit(0)

    if ns.generate:
        output = generate_completions(ns.generate, prog)
        sys.stdout.write(output)
        sys.exit(0)

    if not ns.method_or_url:
        print_short_help(prog)
        sys.exit(0)

    # Parse method and URL
    method_or_url = ns.method_or_url
    request_items = ns.request_items + remaining

    method = None
    url_str = None

    if method_or_url.upper() in HTTP_METHODS:
        method = method_or_url.upper()
        if request_items:
            url_str = request_items[0]
            request_items = request_items[1:]
        else:
            sys.stderr.write(f"{prog}: error: the following required arguments were not provided:\n  <[METHOD] URL>\n\nUsage: {prog} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.\n")
            sys.exit(1)
    else:
        url_str = method_or_url

    # Parse format options
    format_options = {}
    if ns.format_options:
        for opt in ns.format_options.split(','):
            opt = opt.strip()
            if ':' in opt:
                k, _, v = opt.partition(':')
                format_options[k.strip()] = v.strip()

    json_indent = int(format_options.get('json.indent', 4))
    json_format = format_options.get('json.format', 'true').lower() != 'false'
    headers_sort = format_options.get('headers.sort', 'true').lower() != 'false'

    # Determine pretty mode
    is_tty = sys.stdout.isatty()
    no_color = bool(os.environ.get('NO_COLOR'))

    if ns.pretty:
        pretty = ns.pretty
    elif no_color:
        pretty = 'format'
    elif is_tty:
        pretty = 'all'
    else:
        pretty = 'none'

    do_color = pretty in ('all', 'colors')
    do_format = pretty in ('all', 'format')
    theme = ns.style or 'auto'

    # Determine print format
    print_fmt = ns.print_format
    verbose = ns.verbose

    if verbose >= 1:
        print_fmt = 'HhBb'
        if verbose >= 2:
            print_fmt = 'HhBbm'
        if not ns.show_all:
            ns.show_all = True

    if ns.headers:
        print_fmt = 'h'
    elif ns.body:
        print_fmt = 'b'
    elif ns.meta:
        print_fmt = 'm'

    if not print_fmt:
        print_fmt = 'hb'

    pr_H = 'H' in print_fmt
    pr_B = 'B' in print_fmt
    pr_h = 'h' in print_fmt
    pr_b = 'b' in print_fmt
    pr_m = 'm' in print_fmt

    # Read stdin if needed
    ignore_stdin = ns.ignore_stdin
    stdin_body = None

    if not ignore_stdin and not sys.stdin.isatty():
        try:
            stdin_body = sys.stdin.buffer.read()
        except Exception:
            pass

    # Parse request items
    try:
        item_headers, body_params, query_params, files, body_file = parse_request_items(request_items)
    except SystemExit:
        raise
    except Exception as e:
        sys.stderr.write(f"{prog}: error: {e}\n")
        sys.exit(1)

    # Determine modes
    mode_json = ns.json
    mode_form = ns.form
    mode_multipart = ns.multipart

    # Detect body presence
    has_body_data = bool(body_params or files or ns.raw is not None or body_file)

    # Conflict check
    if stdin_body is not None and has_body_data:
        sys.stderr.write(f"{prog}: error: Request body (from stdin) and request data (key=value) cannot be mixed. Pass --ignore-stdin to ignore standard input.\n")
        sys.exit(1)

    if stdin_body is not None and not stdin_body:
        # Empty stdin - treated as body
        pass

    # Determine method
    if method is None:
        if has_body_data or stdin_body is not None:
            method = 'POST'
        else:
            method = 'GET'

    # Build body and determine content type
    body_bytes = None
    body_content_type = None
    is_json_mode = False
    is_form_mode = False

    if ns.raw is not None:
        body_bytes = ns.raw.encode('utf-8')
        if mode_form or mode_multipart:
            is_form_mode = True
            body_content_type = 'application/x-www-form-urlencoded'
        else:
            is_json_mode = True
            body_content_type = 'application/json'

    elif body_file:
