        # No auto content-type for @file body

    elif stdin_body is not None:
        body_bytes = stdin_body
        if mode_form or mode_multipart:
            is_form_mode = True
            body_content_type = 'application/x-www-form-urlencoded'
        else:
            is_json_mode = True
            body_content_type = 'application/json'

    elif body_params or files:
        if mode_multipart or (files and not mode_form):
            body_bytes, body_content_type = build_multipart_body(body_params, files)
            is_form_mode = True
        elif mode_form:
            body_str = build_form_body(body_params)
            body_bytes = body_str.encode('utf-8')
            body_content_type = 'application/x-www-form-urlencoded'
            is_form_mode = True
        else:
            # JSON (default)
            body_str = build_json_body(body_params)
            body_bytes = body_str.encode('utf-8')
            body_content_type = 'application/json'
            is_json_mode = True

    # Explicit mode flags override detection
    if mode_json:
        is_json_mode = True
        is_form_mode = False
        if body_bytes is None and not body_content_type:
            body_content_type = 'application/json'
    elif mode_form or mode_multipart:
        is_form_mode = True
        is_json_mode = False
        if body_bytes is None and not body_content_type:
            body_content_type = 'application/x-www-form-urlencoded'

    # Check user-provided content-type in item_headers
    user_ct = None
    for name, value in item_headers:
        if name.lower() == 'content-type' and value is not None:
            user_ct = value

    # Determine URL scheme
    default_scheme = ns.default_scheme or 'http'
    if force_https or ns.https:
        default_scheme = 'https'

    url_str = normalize_url(url_str, default_scheme)

    # Parse URL
    parsed = urllib.parse.urlparse(url_str)

    # Extract URL auth
    url_auth = None
    if parsed.username:
        url_auth = (parsed.username, parsed.password or '')
        # Rebuild netloc without auth
        netloc = parsed.hostname
        if parsed.port:
            netloc += f':{parsed.port}'
        parsed = parsed._replace(netloc=netloc)

    # Add query params
    existing_qp = urllib.parse.parse_qsl(parsed.query, keep_blank_values=True)
    all_qp = existing_qp + query_params
    if all_qp:
        new_query = urllib.parse.urlencode(all_qp)
        parsed = parsed._replace(query=new_query)

    # Ensure path
    if not parsed.path:
        parsed = parsed._replace(path='/')

    url = urllib.parse.urlunparse(parsed)

    # Load session
    session_file = ns.session or ns.session_read_only
    session_data = None
    cookie_jar = None
    sess_headers = []

    if session_file:
        session_data = load_session(session_file)
        sess_headers = [(h['name'], h['value']) for h in session_data.get('headers', [])]
        cookie_jar = list(session_data.get('cookies', []))
        sess_auth = session_data.get('auth', {})
        if sess_auth.get('type') and not ns.auth_type:
            ns.auth_type = sess_auth['type']
            ns.auth = sess_auth.get('raw_auth')

    # Auth
    auth_type = ns.auth_type
    auth_creds = ns.auth

    if ns.bearer:
        auth_type = 'bearer'
        auth_creds = ns.bearer

    # URL auth takes precedence for URL-embedded
    if url_auth and not auth_creds:
        auth_type = 'basic'
