    # Digest auth is handled during actual request (needs challenge)

    # Build headers in correct order
    # The ordering is complex - see analysis above

    # Track which headers have been set by item_headers (to avoid duplicates)
    item_header_names_lower = set()
    item_headers_filtered = []
    for name, value in item_headers:
        if value is None:
            # Removal
            item_header_names_lower.add(name.lower())
        else:
            item_headers_filtered.append((name, value))
            item_header_names_lower.add(name.lower())

    # Build ordered header list
    headers_ordered = []

    def add_header(name, value):
        """Add header if not removed by item_headers."""
        if name.lower() not in item_header_names_lower:
            headers_ordered.append((name, value))

    def has_header(headers, name):
        """Check if header exists in list."""
        nl = name.lower()
        return any(h[0].lower() == nl for h in headers)

    # 1. URL auth (if embedded in URL) comes FIRST
    if url_auth and auth_header_value:
        if 'authorization' not in item_header_names_lower:
            headers_ordered.append(('Authorization', auth_header_value))
            # Mark that auth has been added so we don't add it again later
            url_auth_added = True
        else:
            url_auth_added = False
    else:
        url_auth_added = False

    # 2. Standard headers
    add_header('Accept-Encoding', 'gzip, deflate, br, zstd')
    add_header('User-Agent', USER_AGENT)
    add_header('Connection', 'keep-alive')

    # 3. Session headers (before custom headers from items)
    for name, value in sess_headers:
        if name.lower() not in item_header_names_lower:
            if not has_header(headers_ordered, name):
                headers_ordered.append((name, value))

    # 4. JSON mode: Accept + Content-Type go before custom headers
    if is_json_mode:
        if not has_header(headers_ordered, 'Accept') and 'accept' not in item_header_names_lower:
            headers_ordered.append(('Accept', 'application/json, */*;q=0.5'))
