        if ct and not has_header(headers_ordered, 'Content-Type') and 'content-type' not in item_header_names_lower:
            headers_ordered.append(('Content-Type', ct))

    # 5. Form mode: Content-Type goes before custom headers, Accept after
    elif is_form_mode:
        ct = user_ct or body_content_type
        if ct and not has_header(headers_ordered, 'Content-Type') and 'content-type' not in item_header_names_lower:
            headers_ordered.append(('Content-Type', ct))

