            flag_auth_added = True
        else:
            flag_auth_added = False
    else:
        flag_auth_added = False

    # 7. Custom headers from request items
    for name, value in item_headers_filtered:
        headers_ordered.append((name, value))

    # 8. Non-JSON mode: Accept after custom headers
    if not is_json_mode:
        if not has_header(headers_ordered, 'Accept') and 'accept' not in item_header_names_lower:
            headers_ordered.append(('Accept', '*/*'))

    # 9. Content-Encoding (from compress) - added later
    # 10. Content-Length - added later
    # 11. Host - always last

    # Display path for request line
    display_path = parsed.path or '/'
    if parsed.query:
