        user_has_ce = 'content-encoding' in item_header_names_lower
        if not user_has_ce:
            compressed = deflate_compress(body_bytes)
            if len(compressed) < len(body_bytes) or compress_level > 1:
                body_bytes = compressed
                headers_ordered.append(('Content-Encoding', 'deflate'))

    # Content-Length (auto, before Host)
    if body_bytes is not None:
        if 'content-length' not in item_header_names_lower:
