        if 'content-length' not in item_header_names_lower:
            headers_ordered.append(('Content-Length', '0'))

    # Host (always last)
    host_value = parsed.netloc
    if not has_header(headers_ordered, 'Host') and 'host' not in item_header_names_lower:
        headers_ordered.append(('Host', host_value))

    # Build final headers list for actual request (as dict for sending)
    final_headers = {}
    for name, value in headers_ordered:
