    # Parse proxies
    proxies_list = []
    if ns.proxies:
        for proxy_spec in ns.proxies:
            colon_idx = proxy_spec.find(':')
            if colon_idx > 0:
                proto = proxy_spec[:colon_idx]
                purl = proxy_spec[colon_idx+1:]
                proxies_list.append((proto, purl))

    # --curl mode
    if ns.curl:
        if ns.offline:
            sys.stderr.write("Warning: Ignored --offline\n")
        if ns.print_format:
            sys.stderr.write("Warning: Ignored -p/--print\n")

        # Build headers list for curl (exclude auto headers)
        curl_headers = []
        auto_names = {'accept-encoding', 'user-agent', 'connection', 'host', 'content-length'}
        for name, value in headers_ordered:
            if name.lower() not in auto_names:
                curl_headers.append((name, value))

        # Form params for curl
        curl_form_params = None
        curl_body = body_bytes
        if is_form_mode and body_params and not files and 'multipart' not in (body_content_type or ''):
            curl_form_params = [(k, v) for _, k, v in body_params]
            curl_body = None

